export class DeviceCapabilitiesDetector{constructor(e){this.targetElements=[];const t=document.getElementById(e);if(t)this.targetElements.push(t);else try{const t=document.querySelectorAll(e);this.targetElements=Array.from(t)}catch(e){}this.mediaQuery=window.matchMedia("(hover: hover) and (pointer: fine)"),this.handleDeviceChange=this.handleDeviceChange.bind(this),this.handleKeyDown=this.handleKeyDown.bind(this),this.hasKeyboardDetected=!1}initialize(){0!==this.targetElements.length&&(this.updateInterfaceVisibility(),this.mediaQuery.addEventListener("change",this.handleDeviceChange),window.addEventListener("keydown",this.handleKeyDown,{once:!0}))}handleDeviceChange(){this.updateInterfaceVisibility()}handleKeyDown(){this.hasKeyboardDetected=!0,this.updateInterfaceVisibility()}updateInterfaceVisibility(){this.targetElements.forEach(e=>{this.mediaQuery.matches||this.hasKeyboardDetected?e.classList.remove("hidden"):e.classList.add("hidden")})}}